import React, { useState } from "react";
import WebflowFormSlot, { trackConversion } from "../../lib/webflowForm.jsx";

/*
  TIA Answer Engine Optimization PPC Landing Page

  Ported 2026-09-23 from Noah's standalone design export ("AEO Landing Page standalone.html").
  Copy, layout and imagery are the export's, unchanged, with four deliberate differences:
    1. Hero collage is three media tiles at their natural aspect ratios (video, Gemini card,
       Google Business Profile card). The export's fourth tile, a static pink search card, cropped
       every image into a portrait frame; it is gone and the Vimeo loop carries the search motion.
    2. The form is the native Webflow Form Block, adopted at mount (see src/lib/webflowForm.jsx),
       so submissions, the thank-you redirect, Lead Legend and the Make receipt all work.
    3. Logo links to the homepage were removed (PPC LP rule: no exit links). Footer carries the
       privacy and terms links like the SEO LP.
    4. Sofia Pro loads from TIA's Adobe Fonts kit (mfz5gdk) as `sofia-pro`, not from OTF files.
       Font Awesome icons rely on the site-wide FA kit that theinfluenceagency.com already loads.

  Every class is prefixed `aeo-` and every rule scoped under `.tia-aeo`, because the Webflow
  site's global stylesheet leaks into anything with a matching class name.
*/

